    question: '物質が燃えるときの酸素の役割について、①木炭（炭素）が燃えるときの化学反応を言葉で表せ　②空気中の酸素の割合は約何%か　③燃焼に必要な3つの条件を答えよ。',
    answer: '①炭素＋酸素→二酸化炭素　②約21%　③燃えるもの（可燃物）・酸素・発火点以上の温度。',
    hint: '燃焼の三要素：可燃物・酸素・発火点。空気：窒素78%・酸素21%。',
    explanation:
      '【何を聞かれているか】木炭が燃える反応を言葉で、空気中の酸素の割合、燃焼の3条件。\n【なぜその式なのか】燃えるとは**酸素と激しく結びついて光と熱を出す**こと。炭素は酸素と結びついて二酸化炭素になる。空気は窒素約78%・酸素約21%。燃えるには**燃えるもの・酸素・発火点以上の温度**の3つが全部いる。\n【ステップ1】①炭素＋酸素→二酸化炭素。\n【ステップ2】②約21%。\n【ステップ3】③燃えるもの・酸素・発火点以上の温度。\n【答え】①炭素＋酸素→二酸化炭素 ②約21% ③燃えるもの・酸素・発火点以上の温度\n【確かめ】1つでも取り除けば火は消える（水→温度、砂・ふた→酸素、燃料を取る→燃えるもの）。酸素が足りないと一酸化炭素ができる。\n【よくあるまちがい】空気の大部分を酸素と思う。**いちばん多いのは窒素**。',
